<template><div class="page"><div class="page-head"><div><h1 class="page-title">自动回复</h1><div class="page-subtitle">配置关键词、关注与事件触发的回复规则</div></div><el-button type="primary" @click="edit({})">新建规则</el-button></div><div class="surface table-surface"><el-table :data="list" v-loading="loading"><el-table-column prop="ruleName" label="规则名称"/><el-table-column prop="matchValue" label="匹配内容"/><el-table-column prop="replyType" label="消息类型"/><el-table-column prop="replyContent" label="回复内容" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-popconfirm title="确定删除规则？" @confirm="remove(row.ruleId)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pager"><el-pagination layout="prev,pager,next" :total="total" @current-change="p=>{params.page=p;load()}"/></div></div><el-dialog v-model="dialog" :title="form.ruleId?'编辑规则':'新建规则'" width="620"><el-form label-width="90"><el-form-item label="规则名称"><el-input v-model="form.ruleName"/></el-form-item><el-form-item label="匹配内容"><el-input v-model="form.matchValue" placeholder="如 subscribe、关键词或菜单 KEY"/></el-form-item><el-form-item label="匹配模式"><el-switch v-model="form.exactMatch" active-text="精确匹配"/></el-form-item><el-form-item label="消息类型"><el-select v-model="form.replyType"><el-option label="文本" value="text"/><el-option label="图片" value="image"/><el-option label="语音" value="voice"/><el-option label="视频" value="video"/><el-option label="图文" value="news"/></el-select></el-form-item><el-form-item label="回复内容"><el-input v-model="form.replyContent" type="textarea" :rows="5" placeholder="文本内容或素材 mediaId / 图文 JSON"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.status"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const list=ref([]),total=ref(0),loading=ref(false),dialog=ref(false),params=reactive({page:1,limit:10}),form=reactive({});async function load(){loading.value=true;try{const r=await api.rules(params);list.value=r.page.list;total.value=r.page.totalCount}finally{loading.value=false}}function edit(row){Object.assign(form,{ruleId:null,ruleName:'',matchValue:'',exactMatch:false,replyType:'text',replyContent:'',status:true},row);dialog.value=true}async function save(){if(form.ruleId)await api.updateRule(form);else await api.saveRule(form);dialog.value=false;ElMessage.success('已保存');load()}async function remove(id){await api.deleteRules([id]);ElMessage.success('已删除');load()}onMounted(load)</script><style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
